private void enlarge(final int size) {
    if (size < 0) {
        throw new IllegalArgumentException("requested size must be non‑negative");
    }
    if (size == 0) {
        return;
    }
    int currentLen = this.length;                // number of bytes already stored
    int currentCap = this.bytes.length;           // current capacity of the backing array
    if (currentCap - currentLen >= size) {
        // enough space already
        return;
    }
    int newCap = Math.max(currentCap * 2, currentLen + size);
    byte[] newBytes = new byte[newCap];
    System.arraycopy(this.bytes, 0, newBytes, 0, currentLen);
    this.bytes = newBytes;
}

