private void moveAllListNodes(DoublyLinkedList<E> list){  
    if (list == null || list == this) return;  
    if (list.size == 0) return;  
    // Update list nodes to point to this list  
    Node<E> curr = list.head;  
    while (curr != null) {  
        curr.list = this;  
        curr = curr.next;  
    }  
    // Attach nodes from source list to this list  
    if (this.size == 0) {  
        this.head = list.head;  
        this.tail = list.tail;  
        this.size = list.size;  
    } else {  
        this.tail.next = list.head;  
        list.head.prev = this.tail;  
        this.tail = list.tail;  
        this.size += list.size;  
    }  
    // Reset the source list  
    list.head = null;  
    list.tail = null;  
    list.size = 0;  
}

