@Override public void generateGraph(Graph<V,E> target,Map<String,V> resultMap) {
    if (target == null || resultMap == null) {
        return;
    }
    // Build partition sets from the keys of the map
    java.util.Map<String, java.util.List<V>> partitions = new java.util.HashMap<>();
    for (java.util.Map.Entry<String,V> entry : resultMap.entrySet()) {
        String key = entry.getKey();
        V value = entry.getValue();
        if (value == null) {
            continue;
        }
        partitions.computeIfAbsent(key, k -> new java.util.ArrayList<>()).add(value);
        target.addVertex(value);
    }
    // Create a complete bipartite graph between different partitions
    java.util.List<String> keys = new java.util.ArrayList<>(partitions.keySet());
    for (int i = 0; i < keys.size(); i++) {
        java.util.List<V> listA = partitions.get(keys.get(i));
        for (int j = i + 1; j < keys.size(); j++) {
            java.util.List<V> listB = partitions.get(keys.get(j));
            for (V a : listA) {
                for (V b : listB) {
                    target.addEdge(a, b);
                }
            }
        }
    }
}

