private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    if (bucketsByLabel == null || labels == null) {
        return;
    }
    if (minLabel <= 0) {
        // If minLabel is 0 there's nothing to move.
        return;
    }
    if (minLabel >= bucketsByLabel.size()) {
        return;
    }
    Set<Integer> source = bucketsByLabel.get(minLabel);
    if (source == null || source.isEmpty()) {
        return;
    }
    // Ensure bucket 0 exists
    Set<Integer> target;
    if (bucketsByLabel.size() > 0) {
        target = bucketsByLabel.get(0);
    } else {
        target = null;
    }
    if (target == null) {
        target = new HashSet<>();
        if (bucketsByLabel.size() > 0) {
            bucketsByLabel.set(0, target);
        } else {
            // If the list is empty add the target set at index 0
            bucketsByLabel.add(target);
        }
    }
    for (Integer v : source) {
        if (v == null) {
            continue;
        }
        target.add(v);
        if (v >= 0 && v < labels.size()) {
            labels.set(v, 0);
        }
    }
    source.clear();
}

