private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    try {
        if (graph == null || vertices == null) {
            return false;
        }
        int size = vertices.size();
        if (size <= 1) {
            return true;
        }
        for (V u : vertices) {
            if (!graph.containsVertex(u)) {
                return false;
            }
            for (V v : vertices) {
                if (u == v) {
                    continue;
                }
                if (!graph.containsEdge(u, v) && !graph.containsEdge(v, u)) {
                    return false;
                }
            }
        }
        return true;
    } catch (Exception e) {
        return false;
    }
}

