    try{
        int b0 = bb.get(i) & 0xFF;
        if ((b0 & 0x80) == 0){
            sb.append((char)b0);
            return i + 1;
        }
        int numBytes;
        int minVal;
        if ((b0 & 0xE0) == 0xC0){
            numBytes = 2;
            minVal = 0x80;
        } else if ((b0 & 0xF0) == 0xE0){
            numBytes = 3;
            minVal = 0x800;
        } else if ((b0 & 0xF8) == 0xF0){
            numBytes = 4;
            minVal = 0x10000;
        } else {
