        if (codePoint < minVal || codePoint > 0x10FFFF) {
            return i; // overlong or out of range
        }
        sb.appendCodePoint(codePoint);
        return i + numBytes;
    } catch (IndexOutOfBoundsException | BufferUnderflowException e) {
        return i;
    }
