    java.util.List<PathSegmentImpl> segments = new java.util.ArrayList<>();
    if (u == null) {
        return segments;
    }
    String path = u.getRawPath();
    if (path == null || path.isEmpty()) {
        return segments;
    }
    if (path.startsWith("/")) {
        path = path.substring(1);
    }
    String[] parts = path.split("/");
    for (String part : parts) {
        if (part.isEmpty()) {
            continue;
        }
        String segmentText = part;
        if (decode) {
            try {
                segmentText = java.net.URLDecoder.decode(part, "UTF-8");
            } catch (java.io.UnsupportedEncodingException ignored) {
                // UTF-8 is guaranteed to be supported; ignore exceptionally
            }
        }
        segments.add(new PathSegmentImpl(segmentText));
    }
    return segments;
}

