private Object parsePrimitive(JsonPrimitive prim){
    if(prim.isBoolean()){
        return prim.getAsBoolean();
    }else if(prim.isNumber()){
        Number num = prim.getAsNumber();
        if(num.doubleValue() % 1 == 0){
