static long compressTimeBucket(long timeBucket,int dayStep){
    if(dayStep <= 0) return timeBucket;
    try{
        int year  = (int)(timeBucket / 10000L);
        int month = (int)((timeBucket / 100L) % 100L);
        int day   = (int)(timeBucket % 100L);
        if(month < 1 || month > 12 || day < 1 || day > 31) return timeBucket;
        int bucketStartDay = ((day - 1) / dayStep) * dayStep + 1;
        // Ensure the bucket start day does not exceed the last valid day of the month
        // For simplicity we cap to 31; a more accurate check would require month length
        if(bucketStartDay > 31) bucketStartDay = 31;
        return year * 10000L + month * 100L + bucketStartDay;
    }catch(Exception e){
        return timeBucket;
    }
}

