private void checkIfPackedField() throws IOException {
    // Determine if the current field is encoded as a length‑delimited packed value.
    // `fieldTag` holds the current raw tag (field number << 3 | wire type).
    // `WIRETYPE_LENGTH_DELIMITED` is the constant for the length‑delimited wire type.
    if ((this.fieldTag & 0x7) == WIRETYPE_LENGTH_DELIMITED) {
        // Mark that we are now reading a packed repeated field.
        this.isReadingPacked = true;
        // The bytes that will follow represent a packed list; read the length.
        int packedLength = readRawVarint32();
        this.packedBytesRemaining = packedLength;
    } else {
        this.isReadingPacked = false;
    }
}

